-- restore_city_dynamis_mobs.sql
-- ONE-SHOT restore of the standard mobs in the four CITY Dynamis zones:
--   185 Dynamis-San_dOria   186 Dynamis-Bastok
--   187 Dynamis-Windurst    188 Dynamis-Jeuno
--
-- WHY: the retired custom Dungeon system ("theme all 8 dungeons to distinct mob
-- families", commit 422f46855c) repurposed these four Dynamis zones and stripped
-- their standard mob rosters out of the DB. Removing the dungeon system
-- (75ea70f1f1) never put them back, so live AND the laptop test DB both had
-- 185/186/187 completely EMPTY and 188 gutted (18 stale rows) -- a normal
-- Dynamis run would find no mobs.
--
-- The canonical data was never lost from source control: sql/mob_groups.sql and
-- sql/mob_spawn_points.sql still ship the full rosters (a fresh dbtool import
-- restores them). This migration re-applies JUST those four zones to an already
-- populated DB, without re-importing every zone.
--
-- WHAT: clears the four zones (scoped by ZONE -- (mobid>>12)&4095 for spawns,
-- zoneid for groups; NEVER by groupid, which is reused across zones -- that JOIN
-- bug caused the 2026-06-15 server-wide wipe) then re-inserts the stock rows:
--   mob_groups        263 rows  (185:48  186:61  187:63  188:91)
--   mob_spawn_points 1013 rows  (185:237 186:240 187:301 188:235)
-- Idempotent: re-running clears + re-inserts the same stock set. mob_pools and
-- droplists are shared by poolid and were untouched, so they need no restore.
--
-- NOTE: mob data is read at map-server startup, so xi_map must be RESTARTED for
-- the restored mobs to spawn (no hot-reload).
--
-- To apply:
--   sudo mysql xidb < modules/custom/sql/restore_city_dynamis_mobs.sql
--   (then restart xi_map)

SET FOREIGN_KEY_CHECKS=0;

DELETE FROM `mob_spawn_points` WHERE ((`mobid` >> 12) & 4095) IN (185,186,187,188);
DELETE FROM `mob_groups`       WHERE `zoneid` IN (185,186,187,188);

-- ===== mob_groups: 263 rows, zones 185-188 (from sql/mob_groups.sql) =====
/*M!999999\- enable the sandbox mode */ 

-- ===== mob_spawn_points: 1013 rows, zones 185-188 (from sql/mob_spawn_points.sql) =====
/*M!999999\- enable the sandbox mode */ 

SET FOREIGN_KEY_CHECKS=1;
